using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Documents;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace StickyNotes;
// Cloud documents are data, never XAML. Only these explicitly supported types are rebuilt.
internal sealed record SyncSpan(string Text,bool Bold=false,bool Italic=false,bool Underline=false);
internal sealed record SyncBlock(string Kind,List<SyncSpan>? Text=null,List<List<SyncBlock>>? Items=null,string? Image=null,bool Numbered=false);
internal sealed record SyncData(string Id,string Title,string Area,string Color,string ColorMode,bool Pinned,bool Deleted,List<SyncBlock> Blocks);
internal sealed record SyncRevision(int Schema,string[] Parents,SyncData Data) {
 [System.Text.Json.Serialization.JsonIgnore] public string Hash=>SyncJson.Hash(SyncJson.Bytes(this));
}
internal static class SyncJson {
 internal static byte[] Bytes<T>(T value)=>JsonSerializer.SerializeToUtf8Bytes(value);
 internal static string Hash(byte[] bytes)=>Convert.ToHexStringLower(SHA256.HashData(bytes));
 internal static bool Id(string s,int length)=>s!=null&&Regex.IsMatch(s,"^[a-f0-9]{"+length+"}$");
 internal static SyncRevision Read(byte[] bytes,string expected){if(bytes.Length>48*1024*1024)throw new InvalidDataException("Nota na nuvem excede o limite de 48 MB.");var r=JsonSerializer.Deserialize<SyncRevision>(bytes)??throw new InvalidDataException("Revisão vazia.");if(r.Schema!=1||r.Parents==null||r.Parents.Length>1000||r.Parents.Any(p=>!Id(p,64))||!Id(r.Data.Id,32)||r.Hash!=expected)throw new InvalidDataException("Revisão da nuvem inválida. Os arquivos locais foram preservados.");Validate(r.Data);return r;}
 internal static void Validate(SyncData d){if(d.Title==null||d.Title.Length>220||d.Area==null||d.Area.Length>50||d.Area.Length==0||!Regex.IsMatch(d.Color??"","^#[A-Fa-f0-9]{6}$")||!new[]{"Soft","Normal","Pastel","Vivid","Neon","Earth"}.Contains(d.ColorMode))throw new InvalidDataException("Metadados inválidos na nuvem.");int count=0,chars=0;void Walk(List<SyncBlock> blocks,int depth){if(blocks==null||depth>12)throw new InvalidDataException("Documento inválido.");foreach(var b in blocks){if(++count>10000)throw new InvalidDataException("Documento extenso demais.");switch(b.Kind){case "paragraph":foreach(var t in b.Text??throw new InvalidDataException()){chars+=t.Text?.Length??throw new InvalidDataException();if(chars>1000000)throw new InvalidDataException("Texto extenso demais.");}break;case "list":foreach(var item in b.Items??throw new InvalidDataException())Walk(item,depth+1);break;case "image":if(b.Image==null||b.Image.Length>32*1024*1024)throw new InvalidDataException("Imagem extensa demais.");DecodeImage(b.Image);break;default:throw new InvalidDataException("Tipo de bloco desconhecido.");}}}Walk(d.Blocks,0);}
 internal static BitmapSource DecodeImage(string data){byte[] bytes=Convert.FromBase64String(data);if(bytes.Length<24||!bytes.Take(8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}))throw new InvalidDataException("Imagem inválida.");uint w=System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(bytes.AsSpan(16,4)),h=System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(bytes.AsSpan(20,4));if(w==0||h==0||w>16384||h>16384||(ulong)w*h>24000000)throw new InvalidDataException("Dimensões de imagem não suportadas.");using var stream=new MemoryStream(bytes);var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();return image;}
}
internal static class SyncDocument {
 internal static SyncData Capture(Note n,FlowDocument doc)=>new(n.Id,n.Title,n.Area,n.Color,n.ColorMode,n.Pinned,n.Deleted,ReadBlocks(doc.Blocks));
 static List<SyncBlock> ReadBlocks(BlockCollection blocks){var output=new List<SyncBlock>();foreach(Block b in blocks){if(b is Paragraph p){var spans=new List<SyncSpan>();void Walk(InlineCollection inlines){foreach(Inline i in inlines){if(i is Run r)spans.Add(new(r.Text,r.FontWeight>=FontWeights.Bold,r.FontStyle==FontStyles.Italic,r.TextDecorations?.Contains(TextDecorations.Underline[0])==true));else if(i is LineBreak)spans.Add(new("\n"));else if(i is Span s)Walk(s.Inlines);else throw new InvalidDataException("Esta nota contém um elemento que ainda não pode ser sincronizado.");}}Walk(p.Inlines);output.Add(new("paragraph",spans));}else if(b is System.Windows.Documents.List list)output.Add(new("list",Items:list.ListItems.Cast<ListItem>().Select(i=>ReadBlocks(i.Blocks)).ToList(),Numbered:list.MarkerStyle==TextMarkerStyle.Decimal));else if(b is BlockUIContainer ui&&ui.Child is Image image&&image.Source is BitmapSource bitmap){var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var memory=new MemoryStream();encoder.Save(memory);output.Add(new("image",Image:Convert.ToBase64String(memory.ToArray())));}else if(b is Section section)output.AddRange(ReadBlocks(section.Blocks));else throw new InvalidDataException("Esta nota contém um elemento que ainda não pode ser sincronizado.");}return output;}
 internal static FlowDocument Restore(SyncData data){SyncJson.Validate(data);var document=new FlowDocument{PagePadding=new Thickness(0),FontSize=15,LineHeight=23};void Add(BlockCollection blocks,List<SyncBlock> source){foreach(var b in source){if(b.Kind=="paragraph"){var p=new Paragraph();foreach(var t in b.Text!){var r=new Run(t.Text){FontWeight=t.Bold?FontWeights.Bold:FontWeights.Normal,FontStyle=t.Italic?FontStyles.Italic:FontStyles.Normal};if(t.Underline)r.TextDecorations=TextDecorations.Underline;p.Inlines.Add(r);}blocks.Add(p);}else if(b.Kind=="list"){var list=new System.Windows.Documents.List{MarkerStyle=b.Numbered?TextMarkerStyle.Decimal:TextMarkerStyle.Disc};foreach(var entry in b.Items!){var item=new ListItem();Add(item.Blocks,entry);list.ListItems.Add(item);}blocks.Add(list);}else blocks.Add(new BlockUIContainer(new Image{Source=SyncJson.DecodeImage(b.Image!),Width=280,Stretch=Stretch.Uniform,Margin=new Thickness(0,8,0,8)}));}}Add(document.Blocks,data.Blocks);return document;}
}
internal sealed record SyncBaseline(string Head,string Fingerprint);
internal sealed class SyncJournal {
 readonly string root;internal Dictionary<string,SyncRevision> Revisions=new();internal Dictionary<string,SyncBaseline> Baseline=new();
 internal SyncJournal(string root){this.root=root;Directory.CreateDirectory(root);foreach(string path in Directory.GetFiles(root,"*.json")){string hash=Path.GetFileNameWithoutExtension(path);if(SyncJson.Id(hash,64))Revisions[hash]=SyncJson.Read(File.ReadAllBytes(path),hash);}string state=Path.Combine(root,"baseline");if(File.Exists(state))Baseline=JsonSerializer.Deserialize<Dictionary<string,SyncBaseline>>(File.ReadAllBytes(state))??throw new InvalidDataException("Estado de sincronização inválido.");}
 internal string Add(SyncRevision revision){string hash=revision.Hash;if(!Revisions.ContainsKey(hash)){Store.Atomic(Path.Combine(root,hash+".json"),SyncJson.Bytes(revision));Revisions[hash]=revision;}return hash;}
 internal void Capture(IEnumerable<SyncData> notes){foreach(var d in notes){string fingerprint=SyncJson.Hash(SyncJson.Bytes(d));if(Baseline.TryGetValue(d.Id,out var previous)&&previous.Fingerprint==fingerprint)continue;string hash=Add(new(1,previous==null?Array.Empty<string>():new[]{previous.Head},d));Baseline[d.Id]=new(hash,fingerprint);}Save();}
 internal void Save()=>Store.Atomic(Path.Combine(root,"baseline"),SyncJson.Bytes(Baseline));
 internal List<(string Head,SyncData Data)> Resolve(){var result=new List<(string,SyncData)>();foreach(var group in Revisions.ToArray().GroupBy(p=>p.Value.Data.Id)){var items=group.ToDictionary(p=>p.Key,p=>p.Value);if(items.Values.Any(r=>r.Parents.Any(p=>!Revisions.ContainsKey(p)||Revisions[p].Data.Id!=r.Data.Id)))throw new InvalidDataException("Histórico incompleto na nuvem; sincronização interrompida para preservar suas notas.");var parents=items.Values.SelectMany(r=>r.Parents).ToHashSet();var heads=items.Where(p=>!parents.Contains(p.Key)).OrderByDescending(p=>p.Value.Data.Deleted).ThenBy(p=>p.Key,StringComparer.Ordinal).ToArray();if(heads.Length==0)throw new InvalidDataException("Histórico cíclico inválido.");var winner=heads[0];if(heads.Length>1){string fingerprint=SyncJson.Hash(SyncJson.Bytes(winner.Value.Data));foreach(var other in heads.Skip(1).Where(p=>!p.Value.Data.Deleted&&SyncJson.Hash(SyncJson.Bytes(p.Value.Data))!=fingerprint)){string id=SyncJson.Hash(Encoding.UTF8.GetBytes(group.Key+other.Key))[..32];var copy=other.Value.Data with{Id=id,Title=other.Value.Data.Title[..Math.Min(other.Value.Data.Title.Length,180)]+" (cópia em conflito)",Deleted=false};string copyHead=Add(new(1,Array.Empty<string>(),copy));result.Add((copyHead,copy));}string merged=Add(new(1,heads.Select(p=>p.Key).OrderBy(p=>p,StringComparer.Ordinal).ToArray(),winner.Value.Data));result.Add((merged,winner.Value.Data));}else result.Add((winner.Key,winner.Value.Data));}return result.GroupBy(p=>p.Item2.Id).Select(g=>g.Last()).ToList();}
}
